program.# The query buttons on their panel. Each:
# Vitufe vya hoja kwenye paneli yao. Kila kimoja hutuma picha ya skrini kwa Google:
#   name: kidokezo cha kitufe;
#   mode: picha ya skrini inakokwenda:
#     "ai": AI ya Google hujibu maagizo mafupi kwa maneno juu ya matokeo ya
#       picha na swali;
#     "chat": AI Mode yenyewe (google.com/ai) kwenye dirisha la programu: programu huweka
#       picha ya skrini na swali humo na kuvituma; dirisha hutokea kando ya eneo
#       lililochaguliwa likiwa na mazungumzo na sehemu ya swali linalofuata pekee; kikishikiliwa,
#       kitufe huuliza swali lako mwenyewe kwa sauti badala ya maagizo mafupi, kikiwa
#       kimeshikiliwa;
#     "answer": vivyo hivyo lakini dirisha limefichwa: jibu huonekana kwenye kadi kando ya
#       eneo lililochaguliwa;
#     "images": utafutaji wa picha bila swali, kwenye dirisha la programu kando ya eneo
#       lililochaguliwa: zinazolingana kabisa mara moja, yaani kurasa zenye picha hii hasa,
#       ambazo mada zake mara nyingi husema ni nani au ni nini kilicho ndani yake;
#   prompt: maagizo mafupi, swali kwa AI, kwa "ai", "chat" na "answer";
#   key: kitufe cha kibodi cha kitufe hiki wakati skrini imegandishwa;
#   icon: "google", "translate", "images" au "question".
# Vitufe vya AI hukaa kwanza kwenye paneli, utafutaji wa picha baada yake.
# Kuingia katika Google kwenye dirisha la programu hufanywa kutoka dirisha la mipangilio,
# “Akaunti ya Google”; wakati hakuna aliyeingia, programu hujitolea kukuingiza inapoanza.
